```ts
export class SafeHtml {
  #markup: string;

  constructor(markup: string) {
    this.#markup = markup;
  }

  toString(): string {
    return this.#markup;
  }
}

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function render(value: unknown): string {
  // Only genuine SafeHtml instances (created by html/raw) are trusted.
  if (value instanceof SafeHtml) {
    return value.toString();
  }

  // Falsy-ish values render as nothing.
  if (value === null || value === undefined || value === true || value === false) {
    return "";
  }

  // Strings are escaped.
  if (typeof value === "string") {
    return escapeHtml(value);
  }

  // Numbers and bigints are safe without escaping (only digits, sign, 'e', 'n').
  if (typeof value === "number" || typeof value === "bigint") {
    return String(value);
  }

  // Arrays are rendered element-by-element, joined with no separator.
  if (Array.isArray(value)) {
    let out = "";
    for (let i = 0; i < value.length; i++) {
      out += render(value[i]);
    }
    return out;
  }

  // Everything else (plain objects, functions, symbols, Date, …) is
  // stringified and then escaped. Duck-typed "safe-looking" objects land here
  // because the instanceof check above already excluded them.
  return escapeHtml(String(value));
}

export function html(
  strings: TemplateStringsArray,
  ...values: unknown[]
): SafeHtml {
  let out = strings[0];
  for (let i = 0; i < values.length; i++) {
    out += render(values[i]);
    out += strings[i + 1];
  }
  return new SafeHtml(out);
}

export function raw(markup: string): SafeHtml {
  return new SafeHtml(markup);
}
```

**Design notes**

- **`instanceof` is the trust boundary.** Only objects whose prototype chain includes `SafeHtml.prototype` (i.e. those produced by `html` / `raw`) bypass escaping. A caller-supplied `{ toString: () => "<script>" }` fails the `instanceof` check and falls through to the final `escapeHtml(String(value))` branch.

- **`#markup` is a true ECMAScript private field**, so no external code can overwrite or read the internal string without going through `toString()`.

- **`escapeHtml` replacement order matters:** `&` is replaced first so that the `&` characters introduced by `&lt;`, `&gt;`, `&quot;`, `&#39;` are not re-escaped in later passes.

- **Numbers/bigints skip escaping** because `String()` can only produce digits, a leading `-`, a `.` , `e`/`E`, `+`, or `n` (for bigint) — none of which are the five dangerous characters.

- **Arrays recurse** through the same `render` function, so nested arrays and `SafeHtml` instances inside arrays are handled uniformly.

- **Nesting is idempotent:** an `html` result interpolated into another `html` template hits the `instanceof SafeHtml` branch and is spliced in verbatim, so no double-escaping occurs.

